//! Windows executable icon and metadata.
//!
//! Generated here by hand (not with `winres`) for a specific reason: the project
//! directory may contain **spaces** (`...\Nueva carpeta\...`) and `windres`
//! breaks when it receives an `-I` flag with spaces (it splits the argument and
//! the preprocessor fails). The solution: work on a temporary copy **without
//! spaces** containing the icon, the `.rc` and the `.o`.
//!
//! - Multi-resolution icon (`assets/scrim-analyzer.ico`, generated by
//!   `cargo run --release --example make_icons`).
//! - Version information (product, description, copyright, version) so the
//!   `.exe` looks trustworthy in File Explorer.

use std::process::Command;

fn main() {
    println!("cargo:rerun-if-changed=assets/scrim-analyzer.ico");
    println!("cargo:rerun-if-changed=build.rs");

    #[cfg(windows)]
    {
        if let Err(e) = incrustar_recurso() {
            println!("cargo:warning=could not embed the icon: {e}");
        }
    }
}

#[cfg(windows)]
fn incrustar_recurso() -> Result<(), String> {
    // Space-free working directory (the project path may contain spaces and
    // windres breaks on them in the -I flag).
    let tmp = std::env::temp_dir().join("scrim-analyzer-build");
    std::fs::create_dir_all(&tmp).map_err(|e| e.to_string())?;
    let ico = tmp.join("app.ico");
    std::fs::copy("assets/scrim-analyzer.ico", &ico).map_err(|e| e.to_string())?;

    // .rc with version information (ASCII) + the icon.
    let rc = tmp.join("app.rc");
    std::fs::write(&rc, version_rc()).map_err(|e| e.to_string())?;

    // windres: .rc → .o
    let obj = tmp.join("app.o");
    let salida = Command::new("windres")
        .current_dir(&tmp)
        .arg(format!("-I{}", tmp.display()))
        .arg(&rc)
        .arg(&obj)
        .status()
        .map_err(|e| format!("windres: {e}"))?;
    if !salida.success() {
        return Err("windres could not compile the .rc".into());
    }

    // The object is passed **directly** to the linker: inside a .a archive,
    // the linker drops members that resolve no symbols (and a resource-only
    // .o resolves none) -> the icon would be lost.
    println!("cargo:rustc-link-arg={}", obj.display());
    Ok(())
}

/// `.rc` with Windows version information + the icon.
#[cfg(windows)]
fn version_rc() -> String {
    let campos = [
        ("ProductName", "Scrim Analyzer"),
        ("FileDescription", "Scrim Analyzer - live scrim score and vision"),
        ("CompanyName", "Scrim Analyzer"),
        ("LegalCopyright", "Copyright (C) 2026 Scrim Analyzer"),
        ("ProductVersion", "1.0.0.0"),
        ("FileVersion", "1.0.0.0"),
        ("InternalName", "scrim-analyzer"),
        ("OriginalFilename", "scrim-analyzer.exe"),
    ];
    let mut rc = String::new();
    rc.push_str("#pragma code_page(65001)\n");
    rc.push_str("1 VERSIONINFO\n");
    rc.push_str("FILEVERSION 1,0,0,0\n");
    rc.push_str("PRODUCTVERSION 1,0,0,0\n");
    rc.push_str("FILEOS 0x40004\n");
    rc.push_str("FILETYPE 0x1\n");
    rc.push_str("BEGIN\nBLOCK \"StringFileInfo\"\n{\nBLOCK \"040904b0\"\n{\n");
    for (k, v) in campos {
        rc.push_str(&format!("VALUE \"{k}\", \"{v}\"\n"));
    }
    rc.push_str("}\n}\nBLOCK \"VarFileInfo\"\n{\nVALUE \"Translation\", 0x409, 0x04b0\n}\n}\n");
    rc.push_str("1 ICON \"app.ico\"\n");
    rc
}

/// On Unix there are no Windows resources: no-op.
#[cfg(not(windows))]
fn incrustar_recurso() -> Result<(), String> {
    let _ = Path::new("");
    Ok(())
}
